import torch
import torch.nn.functional as F


def gen_inputs(ctx, device):
    if ctx["dim"] != -1:
        return {}
    shape = tuple(ctx["output__shape"])
    dtype = getattr(torch, ctx["output__dtype"])
    inp = torch.randn(shape, dtype=dtype, device=device)
    output = F.log_softmax(inp, dim=-1)
    grad_output = torch.randn_like(output)
    return {"grad_output": grad_output, "output": output}


def run(grad_output, output, dim, input_dtype):
    return torch.ops.aten._log_softmax_backward_data(
        grad_output, output, dim, getattr(torch, input_dtype)
    )


def valid(ref_outputs, sol_outputs, inputs, ctx):
    if len(sol_outputs) != 1:
        return {"passed": False, "message": "expected one grad_input", "metrics": {}}
    grad_output, output, dim, input_dtype = inputs
    expected = torch.ops.aten._log_softmax_backward_data(
        grad_output.to(torch.float64),
        output.to(torch.float64),
        dim,
        torch.float64,
    )
    actual = sol_outputs[0]
    expected_dtype = getattr(torch, input_dtype)
    if actual.dtype != expected_dtype:
        return {"passed": False, "message": "grad_input dtype mismatch", "metrics": {}}
    rtol = {
        torch.float16: 1e-3,
        torch.bfloat16: 0.016,
        torch.float32: 1.3e-6,
        torch.float64: 1e-7,
    }.get(actual.dtype, 1.3e-6)
    reduce_dim = grad_output.shape[dim]
    try:
        torch.testing.assert_close(
            actual,
            expected.to(actual.dtype),
            rtol=rtol,
            atol=1e-4 * reduce_dim,
        )
    except AssertionError as exc:
        return {"passed": False, "message": str(exc), "metrics": {}}
    return {"passed": True, "message": "", "metrics": {}}
